def countTripletsWithEvenXOR(a, b, c):
    # Helper to count set bits in x
    def bit_count(x):
        return bin(x).count('1')

    count = 0
    for ai in a:
        for bj in b:
            for ck in c:
                xor_val = ai ^ bj ^ ck
                set_bits = bit_count(xor_val)
                if set_bits % 2 == 0:
                    count += 1
    return count
